+ *   same rationale — reserved for outbound; a loopback-only daemon
+ *   is unaffected. */
+const DAEMON_ENV_ALLOWLIST: ReadonlySet<string> = new Set([
+  "HOME",
+  "LANG",
+  "PATH",
+  "TERM",
+  "TMPDIR",
+  "TMP",
+  "TEMP",
+  "USER",
+  "NIX_PROFILES",
+  "NIX_PATH",
+  "NIX_USER_PROFILE_DIR",
+  "SSL_CERT_FILE",
+  "NIX_SSL_CERT_FILE",
+  "HTTPS_PROXY",
+  "HTTP_PROXY",
+  "NO_PROXY",
+  "https_proxy",
+  "http_proxy",
+  "no_proxy",
+]);
