+/*
+ * revkit rail styles — deliberately minimal (ADR-0017: WCAG 2.2 AA).
+ *
+ * A single-column panel pinned to the right edge on desktop; on
+ * phones (≤ 640px) it becomes a full-width sheet at the bottom of
+ * the page. Colours use CSS variables so a future theme (dark
+ * mode, brand palette) can override without touching this file.
+ * The rail intentionally avoids any dependency on Starlight's
+ * Tailwind layer — it renders inside pages that may not have
+ * loaded that layer (a plain HTML file served by the daemon).
+ */
+
+:root {
+  --revkit-rail-bg: #ffffff;
+  --revkit-rail-fg: #111827;
+  /* `muted` must clear WCAG 2.2 SC 1.4.3 (4.5:1 on rail background)
+   * for the small author-id / anchor line text. #4b5563 on #ffffff
+   * gives ~7.6:1 (verified via axe). #6b7280 sat right on the
+   * threshold and failed on the .revkit-rail__comment background
+   * (which mixes 4% fg onto white → ~#f4f5f6). */
+  --revkit-rail-muted: #4b5563;
+  --revkit-rail-accent: #1d4ed8;
+  --revkit-rail-border: #e5e7eb;
+  --revkit-rail-resolved: #047857;
+  --revkit-rail-danger: #b91c1c;
+  --revkit-rail-focus: #fde68a;
+}
+
+@media (prefers-color-scheme: dark) {
+  :root {
+    --revkit-rail-bg: #0b1220;
