+  root = mkdtempSync(join(tmpdir(), "revkit-lc-"));
+  mkdirSync(join(root, "dist"), { recursive: true });
+  writeFileSync(join(root, "dist", "index.html"), "<h1>x</h1>");
+  daemon = await startDaemon({
+    dir: join(root, "dist"),
+    repoRoot: root,
